SELECT COUNT(*)
FROM pi_session_entry
WHERE session_id = #{sessionId}
  AND run_id = #{runId}

SELECT COALESCE(MAX(seq), 0) + 1
FROM pi_session_entry
WHERE session_id = #{sessionId}

SELECT COUNT(*)
FROM pi_session_entry
WHERE session_id = #{sessionId}

SELECT id, biz_id, session_id, seq, entry_type, parent_id, run_id, payload, created_at
FROM pi_session_entry
WHERE session_id = #{sessionId}
  AND seq > #{anchorSeq}
ORDER BY seq ASC
